use crate::{model::*,unit_support::*};
fn clock(g:&mut Game,seat:usize){g.players[seat].society_zone.card=Some(g.make_card("MSJZ03",seat));}
#[test]fn msjz03_non_disaster_play_conceal_and_paid_reveal_are_rejected_atomically(){let mut g=game();clock(&mut g,0);fund(&mut g,0,"JC049",20);let c=held(&mut g,"JC125",0);for kind in ["deploy","conceal"]{let a=Action{card_id:Some(c.clone()),region:Some(0),..Action::new(kind)};assert!(!g.legal_actions(0).iter().any(|l|l.action==a));reject(&mut g,0,a);}let c=field(&mut g,"JC125",0);g.board_mut(&c).unwrap().face_down=true;reject(&mut g,0,Action{card_id:Some(c),..Action::new("reveal")});let spell=held(&mut g,"JC001",0);reject(&mut g,0,Action{card_id:Some(spell),..Action::new("play")});restore(&mut g);}
#[test]fn msjz03_personal_disaster_play_and_asset_build_still_work(){let mut g=game();clock(&mut g,0);fund(&mut g,0,"JC049",4);let asset=held(&mut g,"JC125",0);act(&mut g,0,Action{card_id:Some(asset),..Action::new("asset")});let c=held(&mut g,"BQ047",0);act(&mut g,0,Action{card_id:Some(c),region:Some(0),..Action::new("deploy")});restore(&mut g);let mut g=game();clock(&mut g,1);let c=held(&mut g,"JC125",0);act(&mut g,0,Action{card_id:Some(c),region:Some(0),..Action::new("deploy")});restore(&mut g);}
fn score(g:&mut Game,seat:usize,destroyed:bool){g.regions[0].destroyed=destroyed;g.effects.push_front(Effect::Score{seat,region:0});g.drive().unwrap();for _ in 0..80{if g.status!="playing"{break}if g.pending.is_some(){resolve_choice(g);}else if !g.stack.is_empty(){pass(g);}else{break}}}
#[test]fn msjz03_preserves_prior_score_and_only_new_wins_score_zero(){let mut g=game();score(&mut g,0,false);let prior=g.player_score(0);assert!(prior>0);clock(&mut g,0);score(&mut g,0,false);assert_eq!(g.player_score(0),prior);score(&mut g,0,true);assert_eq!(g.player_score(0),prior);assert_eq!(g.players[0].destruction_markers,1);assert_eq!(g.msjz03_zero_scores.len(),2);restore(&mut g);let r=crate::jc029_tests::envelope(&g);crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).unwrap();let mut bad=g.clone();bad.msjz03_zero_scores.push(bad.msjz03_zero_scores[0].clone());assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());}
#[test]fn msjz03_third_personal_destroyed_region_wins_without_points(){let mut g=game();clock(&mut g,0);for n in 1..=3{score(&mut g,0,true);assert_eq!(g.player_score(0),0);assert_eq!(g.players[0].destruction_markers,n);assert_eq!(g.status,if n==3{"finished"}else{"playing"});}restore(&mut g);}
#[test]fn msjz03_time_modes_actual_region_and_qualification_change(){
 let mut g=game();clock(&mut g,0);let id=g.players[0].society_zone.card.as_ref().unwrap().id.clone();let t=field(&mut g,"JC125",1);g.board_mut(&t).unwrap().time_markers=3;
 act(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(crate::msjz03::ADD.into()),option:Some("carrier".into()),target_id:Some(t.clone()),..Action::new("activate")});restore(&mut g);top(&mut g);assert_eq!(g.board(&t).unwrap().1.time_markers,4);assert!(g.regions[0].destroyed);
 g.players[0].society_zone.card.as_mut().unwrap().exhausted=false;g.begin_window(Window::Action(0));act(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(crate::msjz03::ADD.into()),option:Some("region".into()),region:Some(1),..Action::new("activate")});top(&mut g);assert_eq!(g.regions[1].card.time_markers,1);
 g.players[0].society_zone.card.as_mut().unwrap().exhausted=false;g.begin_window(Window::Action(0));act(&mut g,0,Action{card_id:Some(id),ability_id:Some(crate::msjz03::ADD.into()),option:Some("carrier".into()),target_id:Some(t.clone()),..Action::new("activate")});g.return_hand(&t);restore(&mut g);top(&mut g);assert!(g.board(&t).is_none());
}
#[test]fn msjz03_generates_real_priest_paid_discard_and_death_observer(){
 let mut g=game();clock(&mut g,0);let id=g.players[0].society_zone.card.as_ref().unwrap().id.clone();let h=held(&mut g,"JC125",0);act(&mut g,0,Action{card_id:Some(id),ability_id:Some(crate::msjz03::GENERATE.into()),region:Some(0),cost_selected:Some(vec![h.clone()]),..Action::new("activate")});assert!(!g.players[0].hand.iter().any(|c|c.id==h));restore(&mut g);top(&mut g);let t=g.regions[0].cards.iter().find(|c|c.definition=="TK009").unwrap().id.clone();assert!(g.board(&t).unwrap().1.generated.is_some());let dead=field(&mut g,"JC125",1);g.remove_dead(&dead,RemovalCause::Destroy);g.drive().unwrap();while g.pending.is_some()||!g.stack.is_empty(){if g.pending.is_some(){resolve_choice(&mut g);}else{top(&mut g);}}assert_eq!(g.board(&t).unwrap().1.time_markers,1);restore(&mut g);g.return_hand(&t);assert!(g.board(&t).is_none());assert!(!g.players.iter().any(|p|p.hand.iter().chain(&p.graveyard).any(|c|c.definition=="TK009")));restore(&mut g);
}
